# ------------------------------------------------------------------ bodies
# A1: per line: a m (m prime, 1 <= a < m). Print a^(m-2) mod m.
A1_R = CPP_STD + cpp("""
    int q; in >> q;
    auto pw = [](long long a, long long e, long long m) {
        long long r = 1; a %= m;
        while (e) { if (e & 1) r = r * a % m; a = a * a % m; e >>= 1; }
        return r;
    };
    while (q--) {
        long long a, m; in >> a >> m;
        out << pw(a, m - 2, m) << "{{NL}}";
    }
""") + END

# A1 W: linear walk — find x with a*x mod m == 1 by trying 1..m-1.
# For m = 1e9+7 the first query alone cannot finish.
A1_W = CPP_STD + cpp("""
    int q; in >> q;
    while (q--) {
        long long a, m; in >> a >> m;
        // WRONG: O(m) scan per query — 1e9+7 steps per query: hours.
        long long x = 1;
        while (x < m && a * x % m != 1 % m) ++x;
        out << x << "{{NL}}";
    }
""") + END

# A2: per line n r: C(n, r) mod 1e9+7. Precompute factorials to 1e6.
A2_R = CPP_STD + cpp("""
    const long long P = 1000000007LL, N = 1000001;
    static long long f[1000001], inv[1000001];
    if (f[0] == 0) {
        f[0] = 1;
        for (long long i = 1; i < N; ++i) f[i] = f[i-1] * i % P;
        auto pw = [](long long a, long long e) {
            long long r = 1; a %= P;
            while (e) { if (e & 1) r = r * a % P; a = a * a % P; e >>= 1; }
            return r;
        };
        inv[N-1] = pw(f[N-1], P - 2);
        for (long long i = N - 1; i >= 1; --i) inv[i-1] = inv[i] * i % P;
    }
    int q; in >> q;
    while (q--) {
        long long n, r; in >> n >> r;
        if (r < 0 || r > n) { out << 0 << "{{NL}}"; continue; }
        out << f[n] * inv[r] % P * inv[n-r] % P << "{{NL}}";
    }
""") + END

# A2 W: one-line-per-row Pascal reconstruction per query — the O(n^2)
# classic: 200000 queries x up to 1e6 rows.
A2_W = CPP_STD + cpp("""
    const long long P = 1000000007LL;
    int q; in >> q;
    // WRONG: rebuild Pascal rows up to n for EVERY query — O(n * r).
    while (q--) {
        long long n, r; in >> n >> r;
        vector<long long> row(r + 2, 1);
        for (long long i = 2; i <= n; ++i) {
            long long prev = 1;
            for (long long j = 1; j <= min(i, r); ++j) {
                long long cur = row[j];
                row[j] = (prev + cur) % P;
                prev = cur;
            }
        }
        out << row[r] << "{{NL}}";
    }
""") + END

# A3: per line N (up to 1e6): print sum_{k=1..N} phi(k) mod 1e9+7.
A3_R = CPP_STD + cpp("""
    const long long P = 1000000007LL, N = 1000001;
    static long long pre[1000001];
    static bool built = false;
    if (!built) {
        static int phi[1000001];
        for (int i = 0; i <= 1000000; ++i) phi[i] = i;
        for (int i = 2; i <= 1000000; ++i)
            if (phi[i] == i)
                for (int j = i; j <= 1000000; j += i) phi[j] -= phi[j] / i;
        pre[0] = 0;
        for (int k = 1; k <= 1000000; ++k) pre[k] = (pre[k-1] + phi[k]) % P;
        built = true;
    }
    int q; in >> q;
    while (q--) {
        int n; in >> n;
        out << pre[n] << "{{NL}}";
    }
""") + END

# A3 W: recomputes phi by gcd-counting per query — O(N log N) per query,
# hopeless at q = 1000, N = 1e6.
A3_W = CPP_STD + cpp("""
    const long long P = 1000000007LL;
    auto gcd2 = [](long long a, long long b) {
        while (b) { long long t = a % b; a = b; b = t; }
        return a;
    };
    int q; in >> q;
    while (q--) {
        int n; in >> n;
        // WRONG: phi(k) by counting coprimes — O(k log k) per k.
        long long s = 0;
        for (int k = 1; k <= n; ++k) {
            int c = 0;
            for (int j = 1; j <= k; ++j) if (gcd2(k, j) == 1) ++c;
            s = (s + c) % P;
        }
        out << s << "{{NL}}";
    }
""") + END

CP_M13_R = CPP_STD + cpp("""
    // CRT: x = a (mod n), x = b (mod m), gcd(n, m) = 1.
    // x = a + n*t, t = (b - a) * n^(-1) (mod m) via EXTENDED EUCLID
    // (m need not be prime).
    int q; in >> q;
    auto inv = [](long long a, long long m) {
        long long r0 = m, r1 = a % m, s0 = 0, s1 = 1;
        while (r1) {
            long long qf = r0 / r1;
            long long tr = r0 - qf * r1; r0 = r1; r1 = tr;
            long long ts = s0 - qf * s1; s0 = s1; s1 = ts;
        }
        return ((s0 % m) + m) % m;  // inverse of a mod m
    };
    while (q--) {
        long long a, n, b, m; in >> a >> n >> b >> m;
        long long t = ((b - a) % m + m) % m;
        t = t * inv(n, m) % m;
        long long x = (a + n * t) % (n * m);
        out << x << "{{NL}}";
    }
""") + END

CP_M13_W = CPP_STD + cpp("""
    // WRONG: reports b (the smallest x satisfying ONLY the second
    // congruence), ignoring the first.
    int q; in >> q;
    while (q--) {
        long long a, n, b, m; in >> a >> n >> b >> m;
        out << b % m << "{{NL}}";
    }
""") + END

# ------------------------------------------------------------------ tests
A1_TESTS = [
    contest_test("third", T("1", "3 1000000007"), T("333333336"),
        "3 * 333333336 = 10^9+7 + 1 = 1 (mod p)."),
    contest_test("seventh", T("1", "7 1000000007"), T("142857144"),
        "7 * 142857144 = 1 (mod p)."),
    contest_test(
        "load: 200000 queries",
        T(*["200000"] + ["5 1000000007"] * 200000),
        T(*["400000003"] * 200000),
        "inv(5) = 400000003: 5 * 400000003 = 2p + 1. Every query is one log-time exponentiation; the O(m) scan W cannot finish the first."),
]

A2_TESTS = [
    contest_test("small", T("2", "5 2", "10 3"), T("10", "120"),
        "C(5,2)=10; C(10,3)=120."),
    contest_test("half of 50", T("1", "50 25"), T("605552882"),
        "C(50,25) mod 1e9+7."),
    contest_test(
        "load: 7 binomials at n = 1e6",
        T("7",
          "1000000 500000",
          "999999 500000",
          "1000000 1",
          "339564 339564",
          "158177 158177",
          "682555 50631",
          "123456 789"),
        T("996692777",
          "998346392",
          "1000000",
          "1",
          "1",
          "13337018",
          "28073395"),
        "Factorial precompute is O(N) ONCE; each query is three multiplications. The per-query Pascal W is O(n*r) — 200000x blowup."),
]

A3_TESTS = [
    contest_test("tiny", T("1", "10"), T("32"),
        "phi: 1,1,2,2,4,2,6,4,6,4 sums to 32."),
    contest_test("prime N", T("1", "97"), T("2902"),
        "sum_{k=1..97} phi(k) = 2902 — verify by the divisor identity: sum_{d|n} phi(d) = n for n = 1..97."),
    contest_test(
        "load: 2000 phi sums, half at N = 1e6",
        T(*["2000"] + ["%d" % x for x in _A3_LOAD_NS]),
        T(*[str(x) for x in _A3_LOAD_WANT]),
        "Sieve once, prefix once; each query is one lookup. Recomputing phi per query is O(N log N) on N = 1e6 — minutes, not seconds."),
]

CP_TESTS = [
    contest_test("textbook", T("1", "2 3 3 4"), T("11"),
        "x = 2 (mod 3), x = 3 (mod 4): x = 11."),
    contest_test("one-congruence trap", T("1", "0 5 3 7"), T("10"),
        "x = 0 (mod 5), x = 3 (mod 7): x = 10, NOT 3 — the W answers 3."),
    contest_test(
        "load: 100 systems",
        T(*["100"] + ["%d %d %d %d" % c for c in _CP_CASES]),
        T(*["%d" % x for x in _CP_ANS]),
        "Each system: one Fermat inverse + O(1) combine. The W reads only the second congruence."),
]

